const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);
const BARS_NUM = 15; // 25
let minWH, bars, shTime;

function setup() {
	createCanvas(400, 400);
	// pixelDensity(1);
	describe("animation of neon bars rotating and changing colors");
	shTime = createFilterShader(fragSrc);

	minWH = max(width, height) * 0.5;
	len = minWH; //  * 0.75;
	pixelDensity(1);
	frameRate(60);

	// generate bars
	bars = [];
	for (let i = 0; i < BARS_NUM; i++) {
		const a = random(TWO_PI);
		const r = minWH - random(random(len, minWH - len));
		const l = random(len * 0.5, len);
		bars.push({a, r, l});
	}
}

function mouseClicked() {
	if (mouseButton === LEFT) setup();
}

function draw() {
	background(0, 0, 8);

	const S = max(width, height);
	let u_bars = []; // for shader uniform
	for (let b of bars) {
		var a = b.a + sin(frameCount * 0.05 * fract(b.a) * abs(sin(b.a + b.r)));
		const x = cos(a) * b.r;
		const y = sin(a) * b.r;
		u_bars.push(x/S, y/S, a, b.l/S);
	}

	// shader
	shTime.setUniform('iResolution', [width * pixelDensity(), height * pixelDensity()]);
	shTime.setUniform("iTime", millis()/1000);
	shTime.setUniform('u_bnum', BARS_NUM);
	shTime.setUniform('u_bars', u_bars);
	filter(shTime);

	// minacoding overlay
  push();
  stroke(0);
	strokeWeight(2)
  fill(255);
  text("#minacoding 24/17 Time", 2, 11);
  pop();
}
